#include "scarlett_cpu64.hpp"
#include <cassert>
#include <iostream>
using namespace genesis;
int main(){GuestMemory64 m;using F=GuestMemory64::Fault;assert(m.map(0x1000,4096,7)==F::none);Cpu64State init;init.gpr[0]=0x1234567880008080ull;init.gpr[2]=0xabcdef1234567890ull;init.gpr[8]=42;init.cf=true;init.zf=true;auto run=[&](auto code){assert(m.write(0x1000,code)==F::none);auto s=executeGuest64(m,0x1000,1,0x1900,nullptr,0,0,0,0,&init);assert(s.steps==1&&s.zf);return s;};assert(run(std::array<uint8_t,2>{0x48,0x98}).gpr[0]==0xffffffff80008080ull);assert(run(std::array<uint8_t,1>{0x98}).gpr[0]==0xffff8080ull);assert(run(std::array<uint8_t,2>{0x66,0x98}).gpr[0]==0x123456788000ff80ull);assert(run(std::array<uint8_t,2>{0x48,0x99}).gpr[2]==0);assert(run(std::array<uint8_t,1>{0x99}).gpr[2]==0xffffffffull);assert(run(std::array<uint8_t,2>{0x66,0x99}).gpr[2]==0xabcdef123456ffffull);auto s=run(std::array<uint8_t,2>{0x49,0x90});assert(s.gpr[0]==42&&s.gpr[8]==init.gpr[0]);assert(!run(std::array<uint8_t,1>{0xf8}).cf);assert(run(std::array<uint8_t,1>{0xf9}).cf);assert(!run(std::array<uint8_t,1>{0xf5}).cf);s=run(std::array<uint8_t,2>{0x86,0xe0});assert(s.gpr[0]==init.gpr[0]);init.gpr[0]=0x1234;s=run(std::array<uint8_t,2>{0x86,0xe0});assert(s.gpr[0]==0x3412);assert(run(std::array<uint8_t,2>{0x48,0x98}).gpr[0]==0x1234);std::cout<<"V37 CPU tests passed\n";}
